#include "App.h"
#include <juce_audio_formats/juce_audio_formats.h>
void App::runRenderTests(std::function<void(bool)> done){
 struct Run{int stage=0;bool finished=false;double started=juce::Time::getMillisecondCounterHiRes(),phase=0;std::uint64_t paints=0,refreshes=0,polls=0,rolls=0;double position=0;juce::File folder,wav;std::vector<var> checks,samples;};
 auto r=std::make_shared<Run>();auto tick=std::make_shared<std::function<void()>>();
 r->folder=juce::File::getSpecialLocation(juce::File::currentExecutableFile).getParentDirectory().getChildFile("test-results/render-"+juce::Uuid().toString());r->folder.createDirectory();r->wav=r->folder.getChildFile("fixture.wav");
 auto check=[r](bool ok,const String& label){r->checks.push_back(object({{"name",label},{"passed",ok}}));if(!ok)throw std::runtime_error(label.toStdString());};
 auto mark=[this,r]{r->phase=juce::Time::getMillisecondCounterHiRes();r->paints=uiPaints;r->refreshes=uiRefreshes;r->polls=playerPolls;r->rolls=roll.playbackRepaints;r->position=number(playback,"position");};
 auto sample=[this,r](const String& label){auto metrics=object({{"phase",label},{"seconds",(juce::Time::getMillisecondCounterHiRes()-r->phase)/1000.},{"full_refreshes",int(uiRefreshes-r->refreshes)},{"app_paints",int(uiPaints-r->paints)},{"player_polls",int(playerPolls-r->polls)},{"roll_updates",int(roll.playbackRepaints-r->rolls)},{"position",number(playback,"position")}});r->samples.push_back(metrics);return metrics;};
 auto finish=[this,r,tick,done](bool ok){if(r->finished)return;r->finished=true;dirty=false;auto output=object({{"passed",ok},{"checks",array(r->checks)},{"samples",array(r->samples)}});r->folder.getChildFile("result.json").replaceWithText(juce::JSON::toString(output));juce::File::getSpecialLocation(juce::File::currentExecutableFile).getParentDirectory().getChildFile("test-results/render-latest.json").replaceWithText(juce::JSON::toString(output));juce::MessageManager::callAsync([tick,done,ok]{*tick={};done(ok);});};
 try{
  juce::AudioBuffer<float> pcm(2,44100*30);pcm.clear();for(int i=0;i<pcm.getNumSamples();++i){double t=double(i)/44100;float value=float(.1*std::sin(juce::MathConstants<double>::twoPi*220*t));for(int ch=0;ch<2;++ch)pcm.setSample(ch,i,value);}
  juce::WavAudioFormat wav;auto stream=std::make_unique<juce::FileOutputStream>(r->wav);std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.release(),44100,2,16,{},0));check(writer&&writer->writeFromAudioSampleBuffer(pcm,0,pcm.getNumSamples()),"Create a local audio-only render fixture");writer.reset();
  Roll isolated;isolated.setSize(900,600);auto state=object({{"ready",true},{"playing",false},{"position",0.},{"active_keys",array({})},{"active_note_indices",array({})}});isolated.updatePlayback(state);auto count=isolated.playbackRepaints;isolated.updatePlayback(state.clone());check(isolated.playbackRepaints==count,"An identical stopped snapshot requests no redraw");
  state=state.clone();state.getDynamicObject()->setProperty("position",1.);isolated.updatePlayback(state);check(isolated.playbackRepaints>count,"A seek invalidates the playhead even while stopped");count=isolated.playbackRepaints;state=state.clone();state.getDynamicObject()->setProperty("active_keys",array({60}));isolated.updatePlayback(state);check(isolated.playbackRepaints>count,"Keyboard audition invalidates the keyboard without moving the playhead");
  count=isolated.playbackRepaints;state=state.clone();state.getDynamicObject()->setProperty("position",2.);isolated.updatePlayback(state,false);check(number(isolated.playback,"position")==2&&isolated.playbackRepaints==count,"A hidden editor receives transport state without drawing");
  startEmptyProject();
 }catch(const std::exception& e){r->checks.push_back(object({{"error",String(e.what())},{"passed",false}}));finish(false);return;}
 *tick=[this,r,mark,sample,check,finish]{try{
  double now=juce::Time::getMillisecondCounterHiRes();if(now-r->started>90000)throw std::runtime_error("Render test timeout");auto* window=findParentComponentOfClass<juce::DocumentWindow>();
  if(r->stage==0&&!locked&&notesReady){r->stage=1;mark();}
  else if(r->stage==1&&now-r->phase>3000){auto v=sample("empty-project-idle");check(int(v["full_refreshes"])<=1&&int(v["roll_updates"])<=1,"An initialized empty project remains idle");dirty=false;r->stage=2;openAudioPath(r->wav.getFullPathName());}
  else if(r->stage==2&&!locked&&notesReady&&!(bool)audio["midi_only"]){roll.displayMode=2;roll.spectral=true;displayMode.setSelectedId(3,juce::dontSendNotification);audioLayer.setSelectedId(2,juce::dontSendNotification);refresh();r->stage=3;mark();}
  else if(r->stage==3&&now-r->phase>2500&&!spectrumPending&&roll.spectrum.isValid()){r->stage=4;mark();}
  else if(r->stage==4&&now-r->phase>3000){auto v=sample("spectrogram-idle");check(int(v["full_refreshes"])==0&&int(v["roll_updates"])==0,"A loaded spectrogram requests no idle redraw or layout");check(int(v["player_polls"])<=14,"Idle transport polling is bounded to four per second");roll.view.zoom=16;roll.follow=true;refresh();r->stage=5;control("play");mark();}
  else if(r->stage==5&&now-r->phase>3500){auto v=sample("playing");check(bool(playback["playing"])&&number(playback,"position")>r->position+2,"Playback and transport position advance");check(roll.view.pan>0,"Follow playback still moves the viewport");check(int(v["full_refreshes"])<=2&&int(v["roll_updates"])>20,"Playback animates the roll without rebuilding the application");control("pause");r->stage=6;mark();}
  else if(r->stage==6&&now-r->phase>1200){check(!bool(playback["playing"]),"Pause still updates transport controls");window->setMinimised(true);r->stage=7;mark();}
  else if(r->stage==7&&now-r->phase>3000){auto v=sample("minimised");check(int(v["roll_updates"])==0&&int(v["player_polls"])<=5,"Minimised window retains state with slow polling and no transport repaint");control("play");r->stage=9;mark();}
  else if(r->stage==9&&now-r->phase>3500){auto v=sample("minimised-playing");check(bool(playback["playing"])&&number(playback,"position")>r->position+1.5&&int(v["roll_updates"])==0,"Minimised audio keeps playing without transport redraws");control("pause");control("seek",5.);r->stage=10;mark();}
  else if(r->stage==10&&now-r->phase>1500){check(std::abs(number(roll.playback,"position")-5.)<.1,"A seek updates the hidden transport model");window->setMinimised(false);r->stage=8;mark();}
  else if(r->stage==8&&now-r->phase>1500){sample("restored-after-seek");check(std::abs(number(roll.playback,"position")-5.)<.1,"Restoring and seeking refreshes the visible playhead");bool handle=false;for(auto* child:roll.getChildren())if(child->getWidth()==20&&child->getHeight()==16)handle|=std::abs(child->getX()-(int(roll.x(5.))-10))<=1;check(handle,"Restoring refreshes the playhead hit target after a hidden seek");auto before=uiRefreshes;refresh();check(uiRefreshes==before+1,"Explicit editing refreshes remain available");finish(true);}
 }catch(const std::exception& e){r->checks.push_back(object({{"error",String(e.what())},{"passed",false}}));finish(false);}};
 struct Poll:juce::Timer{std::shared_ptr<std::function<void()>> fn;explicit Poll(std::shared_ptr<std::function<void()>> f):fn(f){startTimer(50);}void timerCallback()override{if(!*fn){delete this;return;}(*fn)();}};new Poll(tick);
}
